// Görev bankası: 17 kimyasal etkiye göre yaklaşık 2000 köylü derdi, ipucu ve teşekkür cümlesi (Türkçe + İngilizce).
// GenerateInto() elle yazılmış görevlerin üstüne toplam 2000 göreve tamamlar; her görevin kendine ait,
// başka hiçbir görevde geçmeyen bir derdi vardır. Üretim belirlenimcidir (rastgele değil): aynı kod
// her cihazda aynı görevleri, aynı kimliklerle (g0001...) üretir.
// Yeni dert eklemek için Problems dizisine bir satır eklemen yeterli.
using System.Collections.Generic;
