        public static int ProblemCount { get { return Problems.Length; } }

        /// <summary>Elle yazılmış görevlerin üstüne, toplam TotalQuests olana kadar görev üretir.
        /// Her üretilen görev ayrı bir dert kullanır; hiçbir dert iki kez gelmez.</summary>
        public static void GenerateInto(List<QuestData> quests)
        {
            int target = System.Math.Min(TotalQuests - quests.Count, Problems.Length);
            if (target <= 0) return;

            // Etkileri kolaydan zora sırala (iksirin kilidi hangi bina seviyesinde açılıyor), sonra dertleri
            // etkiler arasında sırayla dağıt: art arda hep aynı tür dert gelmesin.
            var byEffect = Problems.GroupBy(p => p.Effect)
                .OrderBy(g => Difficulty(g.Key)).ThenBy(g => (int)g.Key)
                .Select(g => g.ToList()).ToList();
            var seq = new List<Problem>();
            for (int k = 0; seq.Count < Problems.Length; k++)
                foreach (var list in byEffect) if (k < list.Count) seq.Add(list[k]);

            for (int n = 0; n < target; n++)
            {
                var p = seq[n];
                string who = p.Who[n % p.Who.Length];
                var hints = Hints[p.Effect]; var thanks = Thanks[p.Effect];
                var h = hints[(n * 3) % hints.Length];
                var s = thanks[(n * 5 + n / 17) % thanks.Length];
                var t = Twists[(n * 7) % Twists.Length];
                int level = System.Math.Min(40, 1 + n / 50);
                quests.Add(new QuestData
                {
                    Id = "g" + (n + 1).ToString("0000"),
                    VillagerId = who,
                    MinLevel = level,
                    Needed = p.Effect,
                    RewardGold = 15 + 4 * level + (n % 5) * 2,
                    RewardXp = 12 + 3 * level,
                    RewardRaw = new[] { n % 10 == 9 ? "crystal" : RewardRaw[p.Effect] },
                    DialogueTr = new[] { p.Tr, t[0], h[0] },
                    DialogueEn = new[] { p.En, t[1], h[1] },
                    SuccessTr = s[0],
                    SuccessEn = s[1],
                });
            }
        }

        // İksiri yapabilmek için gereken en düşük bina seviyesi (kolay etkiler önce gelsin)
        static int Difficulty(PotionEffect e)
        {
            int best = 99;
            foreach (var c in CompoundDatabase.All)
            {
                if (c.Effect != e) continue;
                var u = BuildingDatabase.UnlockFor(c.Id);
                best = System.Math.Min(best, u != null ? u.Level : 1);
            }
            return best;
        }
    }
}
